// C428 actual Human authoring consumer. Native copies common plot/PNG/map/AI Source.
export const VERSION='quest-dual-human-authoring-ui/1';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i,SHA=/^[0-9a-f]{64}$/;
const copy=x=>structuredClone(x),exact=(x,keys)=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join()===keys.slice().sort().join();
const node=(tag,text='')=>{const x=document.createElement(tag);x.textContent=text;return x;},fail=m=>{throw Error(m);};
const createKeys=['schema_version','request_key','lineage_id','version','draft_id','roster_assignment_id','source_sha256','human_document_sha256','catalog_sha256'];
const publishKeys=['schema_version','request_key','draft_id','content_kind','quest_kind','state','visibility','scheduled_at','mission_id','quest_arc_id','quest_episode_id','source_sha256','config_version','activation_id'];
const validCreate=(v,p)=>exact(v,createKeys)&&v.schema_version==='quest-dual-human-create/3'&&v.request_key===p.p_request&&v.lineage_id===p.p_lineage&&v.version===p.p_expected_version+1&&['request_key','lineage_id','draft_id','roster_assignment_id'].every(k=>UUID.test(v[k]||''))&&['source_sha256','human_document_sha256','catalog_sha256'].every(k=>SHA.test(v[k]||''));
export function createHumanQuestAuthoring({client,api,identity,readEditor,isCurrent,setBusy=()=>{},onPublished=()=>{},onRuntime=()=>{}}={}){
 if(!client?.rpc||!api||typeof identity!=='function'||typeof readEditor!=='function')fail('Consumer Human non collegato.');
 const actor=identity(),journalKey=id=>'tus:quest-human-authoring:'+actor+':'+id;
 let source=null,roster=null,selected=[],tone='',guardrails='',continuity='',receipt=null,version=null,preview=null,published=null,pendingImport=null,pendingPublish=null,knownId=null,slot=null,message='',busy=false,disposed=false,journalError=null;
 const current=()=>!disposed&&identity()===actor&&isCurrent(),currentId=()=>readEditor()?.draft_id;
 function validPending(x){return exact(x,['p_native_draft','p_native_version','p_human_variant','p_roster','p_lineage','p_expected_version','p_request'])&&UUID.test(x.p_native_draft)&&UUID.test(x.p_lineage)&&UUID.test(x.p_request)&&Number.isSafeInteger(x.p_native_version)&&x.p_native_version>0&&Number.isSafeInteger(x.p_expected_version)&&x.p_expected_version>=0&&Array.isArray(x.p_roster)&&x.p_roster.length>=1&&x.p_roster.length<=4&&x.p_roster.every(i=>UUID.test(i))&&exact(x.p_human_variant,['state','mode','document'])&&x.p_human_variant.state==='complete'&&x.p_human_variant.mode==='human';}
 function validPublishPending(x){return exact(x,['p_draft','p_expected_version','p_preview_seal','p_request','p_visibility','p_scheduled_at'])&&UUID.test(x.p_draft)&&UUID.test(x.p_request)&&Number.isSafeInteger(x.p_expected_version)&&x.p_expected_version>0&&SHA.test(x.p_preview_seal)&&x.p_visibility==='open'&&x.p_scheduled_at===null;}
 function journal(){return {schema_version:VERSION,native_draft_id:knownId,tone,guardrails,continuity,selected:copy(selected),pending_import:copy(pendingImport),pending_publish:copy(pendingPublish),create_receipt:copy(receipt),publish_receipt:copy(published)};}
 function persist(){if(!UUID.test(knownId||''))fail('Fonte Native non disponibile.');const text=JSON.stringify(journal());try{localStorage.setItem(journalKey(knownId),text);if(localStorage.getItem(journalKey(knownId))!==text)fail('Journal non confermato.');}catch{fail('Journal Human non conservato: nessuna nuova operazione inviata.');}}
 function restore(){const id=currentId();if(id===knownId)return;knownId=id;journalError=null;source=roster=receipt=version=preview=published=pendingImport=pendingPublish=null;selected=[];tone=guardrails=continuity='';if(!UUID.test(id||''))return;try{const j=JSON.parse(localStorage.getItem(journalKey(id))||'null');if(!j)return;if(!exact(j,['schema_version','native_draft_id','tone','guardrails','continuity','selected','pending_import','pending_publish','create_receipt','publish_receipt'])||j.schema_version!==VERSION||j.native_draft_id!==id||[j.tone,j.guardrails,j.continuity].some(x=>typeof x!=='string')||!Array.isArray(j.selected)||j.selected.some(x=>!UUID.test(x))||(j.pending_import!==null&&!validPending(j.pending_import))||(j.pending_publish!==null&&!validPublishPending(j.pending_publish)))fail('Journal Human non compatibile: conserva la richiesta originale.');tone=j.tone;guardrails=j.guardrails;continuity=j.continuity;selected=j.selected;pendingImport=j.pending_import;pendingPublish=j.pending_publish;receipt=j.create_receipt;published=j.publish_receipt;if(receipt&&(!exact(receipt,createKeys)||receipt.schema_version!=='quest-dual-human-create/3'||!UUID.test(receipt.draft_id)||!UUID.test(receipt.lineage_id)||!Number.isSafeInteger(receipt.version)||receipt.version<1))fail('Ricevuta locale non compatibile.');message='Journal ripreso. Rileggi la versione o verifica la stessa richiesta; nessun invio automatico.';}catch(e){journalError=e.message;message=e.message;pendingImport=pendingPublish=null;receipt=published=null;}}
 async function auth(){if(!current())fail('Accesso editor cambiato.');const a=await client.auth.getUser();if(a.error||a.data?.user?.id!==actor||!current())fail('Sessione Staff non verificata.');}
 async function call(fn){await auth();const v=await fn();await auth();return v;}
 async function rpc(name,p){return call(async()=>{const r=await client.rpc(name,p);if(r.error)throw r.error;return r.data;});}
 async function run(fn){if(busy)return;restore();busy=true;setBusy(true);render();try{await fn();}catch(e){message=e?.message||'Operazione non confermata: conserva il journal.';}finally{busy=false;setBusy(false);render();}}
 function nativeInput(){const e=readEditor();if(!UUID.test(e?.draft_id||'')||!Number.isSafeInteger(e.control_version)||e.control_version<1||e.dirty||e.pending)fail('Salva la bozza IA e risolvi le sue richieste pendenti prima del raccordo Human.');return e;}
 function sourceShape(d){return exact(d,['schema_version','content_kind','catalog_version','npc_bindings','budget_policy_id','variants','quest'])&&d.schema_version==='mission-factory-draft/2'&&d.content_kind==='quest_ai'&&exact(d.variants,['ai'])&&Array.isArray(d.npc_bindings)&&Array.isArray(d.quest?.episodes);}
 async function load(){return run(async()=>{if(pendingImport||pendingPublish)fail('Verifica prima la richiesta conservata.');const e=nativeInput(),v=await call(()=>api.openDraft({draft_id:e.draft_id,content_kind:'quest_ai'}));if(currentId()!==e.draft_id||readEditor().control_version!==e.control_version||v.draft_id!==e.draft_id||v.control_version!==e.control_version||!sourceShape(v.document))fail('Fonte Native cambiata: rileggi la bozza.');const r=await call(()=>api.rosterCatalog({draft_id:e.draft_id}));if(currentId()!==e.draft_id||readEditor().control_version!==e.control_version||!exact(r,['schema_version','draft_id','eligible','assignment'])||r.schema_version!=='mission-factory-quest-roster-catalog/1'||r.draft_id!==e.draft_id||!Array.isArray(r.eligible)||r.eligible.some(x=>!exact(x,['character_id','display_name','village_scope'])||!UUID.test(x.character_id)||typeof x.display_name!=='string'||typeof x.village_scope!=='string'))fail('Catalogo PG Native non compatibile.');source={draft_id:v.draft_id,control_version:v.control_version,document:copy(v.document)};roster=r;if(r.assignment){if(!Array.isArray(r.assignment.member_character_ids)||r.assignment.member_character_ids.some(x=>!r.eligible.some(y=>y.character_id===x)))fail('Gruppo Native non compatibile.');selected=copy(r.assignment.member_character_ids);}else selected=selected.filter(x=>r.eligible.some(y=>y.character_id===x));preview=null;message='Fonte comune riletta dal server. La conduzione Master usa gli stessi PNG e le stesse mappe; il server verifica il gruppo protetto.';});}
 function humanVariant(){if(!source)fail('Rileggi prima la fonte comune.');const q=source.document.quest;return {state:'complete',mode:'human',document:{schema_version:'quest-creation-document/1',direction_mode:'human',quest_kind:q.quest_kind,arc_plan:{episode_order:q.episodes.map(e=>e.episode_key),continuity_notes:continuity,inter_episode_policy_key:null},episodes:q.episodes.map(e=>({episode_key:e.episode_key,phase_keys:e.phases.map(p=>p.step_key)})),editorial:{public_tone:tone,private_guardrails:guardrails},arenas:q.episodes.flatMap(e=>e.maps.filter(m=>m.arena_ref).map(m=>({episode_key:e.episode_key,step_key:m.step_key,template_key:m.arena_ref.template_key,template_version:m.arena_ref.template_version,zone_key:m.arena_ref.zone_key})))}};}
 async function readVersionInternal(){if(!receipt)fail('Manca la ricevuta Human: verifica la stessa richiesta originale.');const r=copy(receipt),id=currentId(),v=await rpc('mission_factory_quest_dual_get_v3',{p_lineage:r.lineage_id,p_version:r.version});if(currentId()!==id||receipt?.request_key!==r.request_key)fail('Versione precedente conservata nel journal della sua fonte.');if(!exact(v,['schema_version','lineage_id','version','document_sha256','document'])||v.schema_version!=='quest-dual-authoring-version/1'||v.lineage_id!==r.lineage_id||v.version!==r.version||v.document_sha256!==r.source_sha256||!exact(v.document,['schema_version','content_kind','catalog_version','npc_bindings','budget_policy_id','variants','quest'])||v.document.schema_version!=='mission-factory-draft/3'||v.document.content_kind!=='quest_dual'||!exact(v.document.variants,['ai','human'])||v.document.variants.human?.state!=='complete'||v.document.variants.human.mode!=='human'||v.document.quest?.roster_assignment_id!==r.roster_assignment_id)fail('Versione Human server non compatibile.');version=copy(v);message='Versione duale '+v.version+' riletta. La variante IA è '+v.document.variants.ai.state+'; la conduzione Master è distinta e fissa.';}
 async function submitImport(p){const submitted=copy(p),id=submitted.p_native_draft,v=await rpc('mission_factory_quest_dual_import_v3',submitted);if(!validCreate(v,submitted))fail('Creazione Human non confermata: conserva la stessa richiesta.');const old=JSON.parse(localStorage.getItem(journalKey(id))||'null');if(!old||old.pending_import?.p_request!==submitted.p_request)fail('Journal precedente cambiato: ricevuta server recuperabile con la richiesta originale.');old.create_receipt=copy(v);old.pending_import=null;old.publish_receipt=null;localStorage.setItem(journalKey(id),JSON.stringify(old));if(currentId()!==id||pendingImport?.p_request!==submitted.p_request){message='Versione Human della fonte precedente committata; rileggila dal suo journal.';return;}receipt=copy(v);pendingImport=null;preview=published=version=null;persist();await readVersionInternal();}
 async function importHuman(){return run(async()=>{if(journalError)fail(journalError);const e=nativeInput();if(pendingImport||pendingPublish)fail('Verifica la stessa richiesta prima di una nuova versione.');if(!source||source.draft_id!==e.draft_id||source.control_version!==e.control_version||selected.length<1||selected.length>4||new Set(selected).size!==selected.length||selected.some(x=>!roster?.eligible.some(y=>y.character_id===x)))fail('Rileggi la fonte e scegli da uno a quattro PG del catalogo.');const p={p_native_draft:source.draft_id,p_native_version:source.control_version,p_human_variant:humanVariant(),p_roster:copy(selected),p_lineage:receipt?.lineage_id||crypto.randomUUID(),p_expected_version:receipt?.version||0,p_request:crypto.randomUUID()};pendingImport=copy(p);persist();await submitImport(p);});}
 async function recoverImport(){return run(async()=>{if(!pendingImport)fail('Nessuna richiesta import da verificare.');await submitImport(pendingImport);});}
 async function readVersion(){return run(readVersionInternal);}
 function assertDirectionSaved(){if(!version)fail('Rileggi la versione Master.');if(source){const saved=JSON.parse(localStorage.getItem(journalKey(currentId()))||'null');if(JSON.stringify(saved?.selected)!==JSON.stringify(selected))fail('Il gruppo è cambiato: crea una nuova versione Master.');const h=version.document.variants.human.document;if(h?.editorial?.public_tone!==tone||h?.editorial?.private_guardrails!==guardrails||h?.arc_plan?.continuity_notes!==continuity)fail('Le indicazioni Master sono cambiate: crea una nuova versione prima dell’anteprima.');}}
 async function previewHuman(){return run(async()=>{if(pendingImport||pendingPublish)fail('Verifica la richiesta pendente.');await readVersionInternal();assertDirectionSaved();const r=copy(receipt),v=await rpc('mission_factory_quest_human_preview_v3',{p_draft:r.draft_id,p_expected_version:r.version});if(receipt?.request_key!==r.request_key)fail('Versione selezionata cambiata.');if(!exact(v,['schema_version','draft_id','draft_version','content_kind','quest_kind','preview_seal','validation_mode','required_variants','validated_variants','errors'])||v.schema_version!=='quest-human-preview/3'||v.draft_id!==r.draft_id||v.draft_version!==r.version||v.content_kind!=='quest_human'||!['one_shot','trama'].includes(v.quest_kind)||v.validation_mode!=='human_only'||JSON.stringify(v.required_variants)!=='["human"]'||!Array.isArray(v.validated_variants)||v.validated_variants.some(x=>x!=='human')||!Array.isArray(v.errors)||(v.preview_seal!==null&&!SHA.test(v.preview_seal)))fail('Anteprima Human non compatibile.');preview=copy(v);message=v.errors.length?'Anteprima bloccata: '+v.errors.map(x=>[x.code,x.path].filter(Boolean).join(' · ')).join('\n'):'Anteprima Human valida; pubblica solo con il comando esplicito riservato Staff.';});}
 function validPublished(v,p){return exact(v,publishKeys)&&v.schema_version==='quest-human-publish-receipt/3'&&v.request_key===p.p_request&&v.draft_id===p.p_draft&&v.content_kind==='quest_human'&&['one_shot','trama'].includes(v.quest_kind)&&v.state==='staff'&&v.visibility==='staff'&&v.scheduled_at===null&&v.mission_id===null&&v.config_version===null&&v.activation_id===null&&UUID.test(v.quest_arc_id||'')&&UUID.test(v.quest_episode_id||'')&&SHA.test(v.source_sha256||'');}
 async function submitPublish(p){const submitted=copy(p),id=currentId(),before=JSON.parse(localStorage.getItem(journalKey(id))||'null'),expected=before?.create_receipt;if(!expected||expected.draft_id!==submitted.p_draft||expected.version!==submitted.p_expected_version||!SHA.test(expected.human_document_sha256||''))fail('Fonte immutabile della pubblicazione non confermata.');const v=await rpc('mission_factory_quest_human_publish_v3',submitted);if(!validPublished(v,submitted)||v.source_sha256!==expected.human_document_sha256)fail('Pubblicazione Human non confermata: conserva la stessa richiesta.');const j=JSON.parse(localStorage.getItem(journalKey(id))||'null');if(!j||j.pending_publish?.p_request!==submitted.p_request)fail('Journal di pubblicazione cambiato: ricevuta recuperabile con la richiesta originale.');j.pending_publish=null;j.publish_receipt=copy(v);localStorage.setItem(journalKey(id),JSON.stringify(j));if(currentId()!==id||pendingPublish?.p_request!==submitted.p_request){message='Pubblicazione precedente committata e conservata nel journal.';return;}published=copy(v);pendingPublish=null;persist();message='Fonte Human pubblicata nella Staff: nessuna puntata avviata e nessun premio assegnato.';onPublished(copy(v));}
 async function publishHuman(){return run(async()=>{if(journalError)fail(journalError);assertDirectionSaved();if(pendingImport||pendingPublish||published||!receipt||!preview||preview.draft_id!==receipt.draft_id||preview.draft_version!==receipt.version||preview.errors.length||!SHA.test(preview.preview_seal||''))fail('Completa una nuova anteprima Human della versione corrente.');pendingPublish={p_draft:receipt.draft_id,p_expected_version:receipt.version,p_preview_seal:preview.preview_seal,p_request:crypto.randomUUID(),p_visibility:'open',p_scheduled_at:null};persist();await submitPublish(pendingPublish);});}
 async function recoverPublish(){return run(async()=>{if(!pendingPublish)fail('Nessuna richiesta di pubblicazione da verificare.');await submitPublish(pendingPublish);});}
 function button(label,fn,off=false){const n=node('button',label);n.type='button';n.disabled=busy||off;n.onclick=()=>{void fn();};return n;}
 function field(label,value,fn,max){const wrap=node('label',label),n=node('textarea');n.value=value;n.maxLength=max;n.disabled=busy||!!pendingImport||!!pendingPublish;n.oninput=()=>{fn(n.value);preview=null;};wrap.append(n);return wrap;}
 function render(){if(!slot||!current())return;restore();slot.replaceChildren();slot.className='mf-card';slot.append(node('h3','Conduzione Master · bozza comune'),node('p',message||'Salva trama, PNG canonici e mappe nel percorso editoriale; poi crea la versione Master senza ricopiarli.'),node('p','IA e Master hanno pubblicazioni distinte. La modalità di una prova avviata resta fissa.'));
 slot.append(button('Rileggi fonte e gruppo Native',load,!!pendingImport||!!pendingPublish));
 if(source){slot.append(node('p','Fonte '+source.draft_id+' · versione '+source.control_version+' · variante IA '+source.document.variants.ai.state));for(const p of roster?.eligible||[]){const l=node('label'),check=node('input');check.type='checkbox';check.checked=selected.includes(p.character_id);check.disabled=busy||!!roster.assignment||!!pendingImport||!!pendingPublish;check.onchange=()=>{selected=check.checked?[...selected,p.character_id]:selected.filter(x=>x!==p.character_id);preview=null;};l.append(check,node('span',p.display_name+' · '+p.village_scope));slot.append(l);}slot.append(field('Tono del Master',tone,x=>{tone=x;},2000),field('Indicazioni riservate di conduzione',guardrails,x=>{guardrails=x;},5000),field('Continuità fra puntate',continuity,x=>{continuity=x;},5000),button(receipt?'Crea nuova versione Master':'Crea versione Master dalla bozza',importHuman,!!pendingImport||!!pendingPublish));}
 if(pendingImport)slot.append(node('p','Richiesta import conservata: '+pendingImport.p_request),button('Verifica stessa richiesta import',recoverImport));
 if(receipt)slot.append(node('p','Human '+receipt.draft_id+' · versione '+receipt.version),button('Rileggi versione storica',readVersion),button('Anteprima Master',previewHuman,!!published||!!pendingImport||!!pendingPublish));
 if(version){const list=node('div');list.append(node('p','PNG canonici: '+version.document.npc_bindings.map(x=>x.actor_key).join(', ')),node('p','Puntate: '+version.document.quest.episodes.map(x=>x.title).join(' · ')));slot.append(list);}
 if(preview)slot.append(button('Pubblica versione Master nella Staff',publishHuman,!!published||!!pendingImport||!!pendingPublish||preview.errors.length>0||!preview.preview_seal));
 if(pendingPublish)slot.append(node('p','Richiesta pubblicazione conservata: '+pendingPublish.p_request),button('Verifica stessa pubblicazione',recoverPublish));
 if(published)slot.append(node('p','Fonte Staff pubblicata: '+published.quest_arc_id+' · puntata '+published.quest_episode_id),button('Gestisci prova con Master',()=>run(async()=>{await readVersionInternal();if(!receipt||published.draft_id!==receipt.draft_id||published.source_sha256!==receipt.human_document_sha256)fail('Versione pubblicata non coerente.');await onRuntime({schema_version:'quest-human-runtime-selection/1',publication:copy(published),lineage_id:receipt.lineage_id,authoring_version:receipt.version});})));}
 return {render(target){slot=target;render();},dispose(){disposed=true;slot=null;},readVersion};
}
